/* 用户按下 Ctrl+C 会触发 SIGINT 信号，产生中断 */
#include <signal.h>
#include <stdio.h>

void handle_sigint(int sig) {
    printf("Received interrupt signal (Ctrl+C)\n");
}

int main() {
    signal(SIGINT, handle_sigint);
    while(1);
    return 0;
}

/* 模拟异常发生后跳转至操作系统处理程序 */
void handle_exception() {
    // 保存上下文
    save_registers();
    // 调用操作系统异常处理函数
    os_exception_handler();
    // 返回原程序执行点
    iret();
}

void interrupt_response() {
    // 保存断点（PC）和机器状态到栈
    push(PC);
    push(PS);

    // 设置关中断状态
    disable_interrupts();

    // 从数据总线读取中断类型号
    int interrupt_type = read_from_data_bus();

    // 跳转到对应的中断服务程序
    jump_to_isr(interrupt_type);
}
